export const blogPosts: BlogPost[] = visibleBlogSlugs.map((slug) => {
  const post = allBlogPosts.find((item) => item.slug === slug);
  if (!post) {
    throw new Error(`Missing blog post: ${slug}`);
  }
  return normalizeSources(post);
});

// ── Load-time validator: fail fast if any post's dateLabel diverges from its
// ISO `date`. Runs during SSR/build/dev/test — a mismatch throws before any
// route can render. Keeps the visible card date honest against the source of
// truth used for sorting, RSS, and sitemaps.
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
] as const;
for (const post of blogPosts) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(post.date)) {
    throw new Error(`blogPosts: invalid ISO date on "${post.slug}": ${post.date}`);
  }
  if (!post.dateLabel) continue;
  const [y, m, d] = post.date.split("-").map(Number);
  const expected = MONTHS[m - 1];
  const label = post.dateLabel;
  const monthOk = label.includes(expected) || label.includes(expected.slice(0, 3));
  const dayOk = new RegExp(`\\b${d}\\b`).test(label);
  const yearOk = label.includes(String(y));
  if (!monthOk || !dayOk || !yearOk) {
    throw new Error(
      `blogPosts: dateLabel "${label}" does not match ISO date "${post.date}" on "${post.slug}".`,
    );
  }
}


export const BLOG_PAGE_SIZE = 12;

export const sortedBlogPosts: BlogPost[] = [...blogPosts].sort((a, b) =>
  b.date.localeCompare(a.date),
);

export const featuredPosts = sortedBlogPosts.slice(0, 4);

// Homepage carousel shows newest posts first — no manual pinning.
export const homepageCarouselPosts: BlogPost[] = [...sortedBlogPosts];



export const blogPageCount = Math.max(
  1,
  Math.ceil(sortedBlogPosts.length / BLOG_PAGE_SIZE),
);

export function getBlogPagePosts(page: number): BlogPost[] {
  const start = (page - 1) * BLOG_PAGE_SIZE;
  return sortedBlogPosts.slice(start, start + BLOG_PAGE_SIZE);
}

export function getBlogPost(slug: string) {
  return blogPosts.find((post) => post.slug === slug);
}

/** Slugify a category or tag label into a URL segment. */
export function slugifyTopic(label: string): string {
  return label
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export type TopicSummary = { label: string; slug: string; count: number };

/** All unique categories with post counts, sorted by count desc then label. */
export const allCategories: TopicSummary[] = (() => {
  const map = new Map<string, TopicSummary>();
  for (const p of sortedBlogPosts) {
    if (!p.category) continue;
    const slug = slugifyTopic(p.category);
    const existing = map.get(slug);
    if (existing) existing.count += 1;
    else map.set(slug, { label: p.category, slug, count: 1 });
  }
  return Array.from(map.values()).sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
})();

/** All unique focus-keyword tags with post counts. */
export const allTags: TopicSummary[] = (() => {
  const map = new Map<string, TopicSummary>();
  for (const p of sortedBlogPosts) {
    for (const kw of p.focusKeywords ?? []) {
      const slug = slugifyTopic(kw);
      if (!slug) continue;
      const existing = map.get(slug);
      if (existing) existing.count += 1;
      else map.set(slug, { label: kw, slug, count: 1 });
    }
  }
  return Array.from(map.values()).sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
})();

export function getPostsByCategorySlug(slug: string): BlogPost[] {
  return sortedBlogPosts.filter((p) => slugifyTopic(p.category) === slug);
}

export function getPostsByTagSlug(slug: string): BlogPost[] {
  return sortedBlogPosts.filter((p) =>
    (p.focusKeywords ?? []).some((kw) => slugifyTopic(kw) === slug),
  );
}

export function getCategoryBySlug(slug: string): TopicSummary | undefined {
  return allCategories.find((c) => c.slug === slug);
}

export function getTagBySlug(slug: string): TopicSummary | undefined {
  return allTags.find((t) => t.slug === slug);
}

